def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    if n >= 2:
        if my[-1] == 'D' and op[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
            return 'C'
    if n < 4:
        opD = op.count('D')
        if opD == 0:
            return 'C'
        if opD == n:
            return 'D'
        return 'C'
    if op[-1] == 'D':
        return 'D'
    return 'C'
